PAYLOAD=''
from pathlib import Path
from datetime import datetime,timezone
import subprocess,os,json,base64,gzip,hashlib,shutil,re,shlex,secrets,difflib,sys
sys.excepthook=sys.__excepthook__
ROOT=Path('/var/www/marketplace.dieseldesigns.co')
def run(args,**kw):return subprocess.run(args,check=True,**kw)
def output(args):return subprocess.check_output(args,text=True).strip()
def note(s):print(s,flush=True)
def main():
 os.chdir(ROOT)
 if output(['git','branch','--show-current'])!='main' or output(['git','status','--porcelain']):raise RuntimeError('Expected clean main.')
 if not output(['git','rev-parse','HEAD']).startswith('6fb12d5'):raise RuntimeError('Repository changed since inspection.')
 run(['git','fetch','origin','main'])
 if output(['git','rev-parse','HEAD'])!=output(['git','rev-parse','origin/main']):raise RuntimeError('Main differs from GitHub.')
 package=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)));manifest=package['files'];originals={}
 for name,item in manifest.items():
  content=item['content']
  if content!=content.rstrip('\n')+'\n' or any(l!=l.rstrip(' \t') for l in content.splitlines()):raise RuntimeError('Package whitespace error: '+name)
  p=Path(name)
  if item['before'] is None:
   if p.exists():raise RuntimeError('Unexpected existing file: '+name)
  else:
   originals[name]=p.read_bytes()
   if hashlib.sha256(originals[name].rstrip()).hexdigest()!=item['before']:raise RuntimeError('Source differs: '+name)
 match=re.search(r'(?m)^\s*(?:export\s+)?DB_NAME\s*=\s*(.*?)\s*$',Path('.env').read_text())
 if not match:raise RuntimeError('DB_NAME not found.')
 vals=shlex.split(match.group(1),comments=True)
 if len(vals)!=1 or not re.fullmatch(r'[A-Za-z0-9_]+',vals[0]):raise RuntimeError('Unexpected database name.')
 db=vals[0];mysql=['mysql','--protocol=socket','-u','root','--batch','--skip-column-names'];socket=output(mysql+['-e','SELECT @@socket'])
 if not socket or ';' in socket or '\n' in socket:raise RuntimeError('Unexpected socket.')
 for table in ['advertising_credits','advertising_credit_transactions']:
  if output(mysql+[db,'-e','SELECT COUNT(*) FROM '+table])!='0':raise RuntimeError('Credit activity changed; inspect before migration: '+table)
 if output(mysql+[db,'-e',"SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='advertising_credit_recurring_grants' AND COLUMN_NAME IN ('expiry_days','schedule_timezone')"])!='0':raise RuntimeError('New schedule schema already exists; inspect before retrying.')
 tables=output(mysql+[db,'-e',"SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_TYPE='BASE TABLE'"]).splitlines()
 if any(not re.fullmatch(r'[A-Za-z0-9_]+',t) for t in tables):raise RuntimeError('Unexpected table name.')
 if any(t in tables for t in ['advertising_credit_lots','advertising_credit_allocations']):raise RuntimeError('Allocation schema already exists.')
 backup=ROOT/'backups'/('credit-dashboard-completion-'+datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S-%f'));backup.mkdir(mode=0o700);stage=backup/'candidate';stage.mkdir()
 note('BACKUP / STAGING: '+str(backup))
 for name in subprocess.check_output(['git','ls-files','-z'],text=True).split('\0'):
  if not name:continue
  p=Path(name)
  if p.parts[0] not in ('app','public','assets','database','tests','scripts','config') or p.is_symlink():continue
  if p.is_file():target=stage/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,target)
 for name,item in manifest.items():
  p=stage/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(item['content'])
  if name.endswith('.php'):run(['php','-l',str(p)])
 configure=backup/'configure.php';configure.write_text(package['configure']);run(['php','-l',str(configure)])
 suites=['AdvertisingCreditCompletionTest','GrandOpeningSaleControlsTest','GrandOpeningSaleAdminTest','AutomaticLaunchScheduleTest','BattleCalendarTest','BattleTieBreakTest','FinalGiveawayWheelTest','SocialContentQueueTest']
 testOriginals={}
 for suite in suites:
  p=stage/'tests'/(suite+'.php');s=p.read_text();testOriginals[p]=p.read_bytes()
  for old in ["require dirname(__DIR__).'/app/bootstrap.php';", "require dirname(__DIR__) . '/app/bootstrap.php';"]:
   if old in s:
    if s.count(old)!=1:raise RuntimeError('Unexpected bootstrap: '+suite)
    s=s.replace(old,"require __DIR__.'/helpers/GrandOpeningPricingBootstrap.php';")
  p.write_text(s)
 migration=manifest['database/migrations/2026_10_28_advertising_credit_controls.sql']['content']
 for suite in suites:
  testdb='cm_sale_test_'+secrets.token_hex(10);created=False
  try:
   note('ISOLATED TEST: '+suite+' — schema only, no customer records copied')
   run(mysql+['-e','CREATE DATABASE `'+testdb+'` CHARACTER SET utf8mb4']);created=True
   run(mysql,input='\n'.join('CREATE TABLE `'+testdb+'`.`'+t+'` LIKE `'+db+'`.`'+t+'`;' for t in tables),text=True)
   run(mysql+[testdb],input=migration,text=True)
   env={'PATH':os.environ.get('PATH','/usr/bin:/bin'),'CM_SALE_TEST_DSN':'mysql:unix_socket='+socket+';dbname='+testdb}
   run(['php',str(stage/'tests'/(suite+'.php'))],env=env,cwd=stage,timeout=180)
  finally:
   if created:run(mysql+['-e','DROP DATABASE `'+testdb+'`'])
 for p,data in testOriginals.items():p.write_bytes(data)
 for name,item in manifest.items():
  if (stage/name).read_bytes()!=item['content'].encode():raise RuntimeError('Staged package differs after tests: '+name)
 note('ALL PRE-INSTALL CHECKS PASSED')
 for name,data in originals.items():
  if Path(name).read_bytes()!=data:raise RuntimeError('Source changed during tests: '+name)
  p=backup/'original'/name;p.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(name,p)
 with (backup/'credit-settings-before.sql').open('wb') as f:run(['mysqldump','--protocol=socket','-u','root','--single-transaction','--complete-insert',db,'advertising_credits','advertising_credit_transactions','advertising_credit_recurring_grants','admin_logs'],stdout=f)
 review=[]
 for name,item in manifest.items():review.extend(difflib.unified_diff(originals.get(name,b'').decode().splitlines(keepends=True),item['content'].splitlines(keepends=True),fromfile='a/'+name,tofile='b/'+name))
 (backup/'review.diff').write_text(''.join(review));installed=[]
 try:
  for table in ['advertising_credits','advertising_credit_transactions']:
   if output(mysql+[db,'-e','SELECT COUNT(*) FROM '+table])!='0':raise RuntimeError('Credit activity appeared during tests; no install.')
  run(mysql+[db],input=migration,text=True)
  for name,item in manifest.items():
   p=Path(name);p.parent.mkdir(parents=True,exist_ok=True)
   if name in originals and p.read_bytes()!=originals[name]:raise RuntimeError('Source changed before install: '+name)
   if name not in originals and p.exists():raise RuntimeError('File appeared before install: '+name)
   installed.append(name);temp=p.with_name(p.name+'.completion-install');shutil.copy2(stage/name,temp);os.replace(temp,p)
  run(['git','diff','--check'])
  for name,item in manifest.items():
   if Path(name).read_bytes()!=item['content'].encode():raise RuntimeError('Installed verification failed: '+name)
  run(['php',str(configure)])
 except Exception:
  for name in reversed(installed):
   if name in originals:shutil.copy2(backup/'original'/name,name)
   else:Path(name).unlink(missing_ok=True)
  note('Files restored. Added schema may remain; inspect before retrying. Configuration rolls back if it fails.')
  raise
 run(['git','add','--',*manifest.keys()]);run(['git','diff','--cached','--check'])
 run(['git','commit','-m','Complete advertising credit controls and Grand Opening dashboard'])
 run(['git','push','origin','main']);run(['git','fetch','origin','main'])
 if output(['git','rev-parse','HEAD'])!=output(['git','rev-parse','origin/main']):raise RuntimeError('Remote verification failed.')
 # Remove only this successful run's disposable schema-test source and configuration script.
 shutil.rmtree(stage);configure.unlink()
 note('INSTALLED: credit expiration, monthly schedule editing, and Grand Opening Control Center.')
 note('SAVED: '+output(['git','log','-1','--oneline']))
 note('WORKING TREE: '+(output(['git','status','--short']) or 'Clean'))
 note('BACKUP: '+str(backup)+' — original files, database rollback, and review diff retained.')
 note('REVIEW: /admin/credits?user_id=4 and /admin/grand-opening')
 note('Event dates, live drawing visibility, and account permissions unchanged.')
if __name__=='__main__':main()
